import numpy as np
import json

def compute_metrics(data, alpha=1.0, tail_threshold=0.9, smooth_factor=0.1):
    ethic = np.mean(data) * alpha
    novelty = np.std(data) * (1 - tail_threshold) * smooth_factor
    return {'ethic': ethic, 'novelty': novelty}

def compute_ven(bridge_synergy, novelty, ethic, mode='balanced'):
    if mode == 'balanced':
        val = bridge_synergy * novelty * ethic
        return np.nan_to_num(val ** (1/3), nan=0.0)
    elif mode == 'discovery':
        val = bridge_synergy * novelty
        return np.nan_to_num(val ** 0.5, nan=0.0)
    elif mode == 'grounded':
        val = ethic ** 0.5
        return np.nan_to_num(bridge_synergy * val, nan=0.0)

dists = ['Cauchy', 'Exponential', 'beta07_08']
results = {}
for dist in dists:
    if dist == 'Cauchy':
        data = np.random.standard_cauchy(150)
    elif dist == 'Exponential':
        data = np.random.exponential(1, 150)
    else:
        data = np.random.beta(0.7, 0.8, 150)
    metrics = compute_metrics(data)
    bridge_synergy = 0.8
    for mode in ['balanced', 'discovery', 'grounded']:
        ven = compute_ven(bridge_synergy, metrics['novelty'], metrics['ethic'], mode)
        results[f'{dist}_{mode}'] = ven

with open('storage/shared/agents/nova/ven_v2_3_results.json', 'w') as f:
    json.dump(results, f)

print("VEN v2.3 robust run completed. Results in ven_v2_3_results.json")
